-- ========================================================

function DoorStateHandle:__init()
    self.controller = nil
end


function DoorStateHandle:__delete()
end


function DoorStateHandle:Start()
    KTool.SetActive(self.controller.gameObject, true)

    assert( self.colorRenderer )

    self.material = self.colorRenderer.material

    --self.state = State.Off   

    self.params = KTool.GetComponent(self.controller.gameObject, typeof(LuaParameters))
    assert( self.params )

    local isInitOpen = LuaParametersReader.Read( self.params, "isInitOpen", LuaParametersType.Bool )

    -- 允许不配置
    if isNotNull(isInitOpen) then 
        if isInitOpen == true then 
            self:ToWalkable()
        else 
            self:ToForbidEnter()
        end 
    end


end




function DoorStateHandle:OnDestroy()
    self.material = nil
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end

-- =========================================== Self ================================================ --


-- 门状态: 允许通行
function DoorStateHandle:ToWalkable()

    self.material:SetColor( "_EmissionColor", Color( 0, 0.845, 1, 1 ) )

end


-- 门状态: 禁止通行
function DoorStateHandle:ToForbidEnter()
    
    self.material:SetColor( "_EmissionColor", Color( 0, 0, 0, 1 ) )

end


return DoorStateHandle

